import{_ as d,a0 as i,w as r,s as l,I as a,x as s,a1 as o,A as n,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"Fedora 中的容器技術：systemd-nspawn | LCTT x X-CMD","titleTemplate":false,"description":"Fedora 中的容器技術：systemd-nspawn | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Fedora 中的容器技術：systemd-nspawn | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Fedora 中的容器技術：systemd-nspawn | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160621 Container technologies in Fedora - systemd-nspawn","title":"Fedora 中的容器技術：systemd-nspawn","tag":"201607","desc":""},"relativePath":"201607/20160621 Container technologies in Fedora - systemd-nspawn.md","filePath":"[post].md"}'),c={name:"201607/20160621 Container technologies in Fedora - systemd-nspawn.md"};function h(m,e,b,g,u,f){const t=i("Link");return r(),l("div",null,[e[18]||(e[18]=a("h1",{id:"fedora-中的容器技術-systemd-nspawn",tabindex:"-1"},[s("Fedora 中的容器技術：systemd-nspawn "),a("a",{class:"header-anchor",href:"#fedora-中的容器技術-systemd-nspawn","aria-label":"Permalink to “Fedora 中的容器技術：systemd-nspawn”"},"​")],-1)),e[19]||(e[19]=a("p",null,[s("歡迎來到“Fedora 中的容器技術”系列！本文是該系列文章中的第一篇，它將説明你可以怎樣使用 Fedora 中各種可用的容器技術。本文將學習 "),a("code",null,"systemd-nspawn"),s(" 的相關知識。")],-1)),e[20]||(e[20]=a("h3",{id:"容器是什麼",tabindex:"-1"},[s("容器是什麼？ "),a("a",{class:"header-anchor",href:"#容器是什麼","aria-label":"Permalink to “容器是什麼？”"},"​")],-1)),a("p",null,[e[1]||(e[1]=s("一個容器就是一個用户空間實例，它能夠在與託管容器的系統（叫做宿主系統）相隔離的環境中運行一個程序或者一個操作系統。這和 ",-1)),e[2]||(e[2]=a("code",null,"chroot",-1)),e[3]||(e[3]=s(" 或 ",-1)),o(t,{href:"https://en.wikipedia.org/wiki/Virtual_machine"},{default:n(()=>[...e[0]||(e[0]=[s("虛擬機",-1)])]),_:1}),e[4]||(e[4]=s(" 的思想非常類似。運行在容器中的進程是由與宿主操作系統相同的內核來管理的，但它們是與宿主文件系統以及其它進程隔離開的。",-1))]),e[21]||(e[21]=p(`<h3 id="什麼是-systemd-nspawn" tabindex="-1">什麼是 systemd-nspawn？ <a class="header-anchor" href="#什麼是-systemd-nspawn" aria-label="Permalink to “什麼是 systemd-nspawn？”">​</a></h3><p>systemd 項目認為應當將容器技術變成桌面的基礎部分，並且應當和用户的其餘系統集成在一起。為此，systemd 提供了 <code>systemd-nspawn</code>，這款工具能夠使用多種 Linux 技術創建容器。它也提供了一些容器管理工具。</p><p><code>systemd-nspawn</code> 和 <code>chroot</code> 在許多方面都是類似的，但是前者更加強大。它虛擬化了文件系統、進程樹以及客户系統中的進程間通信。它的吸引力在於它提供了很多用於管理容器的工具，例如用來管理容器的 <code>machinectl</code>。由 <code>systemd-nspawn</code> 運行的容器將會與 systemd 組件一同運行在宿主系統上。舉例來説，一個容器的日誌可以輸出到宿主系統的日誌中。</p><p>在 Fedora 24 上，<code>systemd-nspawn</code> 已經從 systemd 軟件包分離出來了，所以你需要安裝 <code>systemd-container</code> 軟件包。一如往常，你可以使用 <code>dnf install systemd-container</code> 進行安裝。</p><h3 id="創建容器" tabindex="-1">創建容器 <a class="header-anchor" href="#創建容器" aria-label="Permalink to “創建容器”">​</a></h3><p>使用 <code>systemd-nspawn</code> 創建一個容器是很容易的。假設你有一個專門為 Debian 創造的應用，並且無法在其它發行版中正常運行。那並不是一個問題，我們可以創造一個容器！為了設置容器使用最新版本的 Debian（現在是 Jessie），你需要挑選一個目錄來放置你的系統。我暫時將使用目錄 <code>~/DebianJessie</code>。</p><p>一旦你創建完目錄，你需要運行 <code>debootstrap</code>，你可以從 Fedora 倉庫中安裝它。對於 Debian Jessie，你運行下面的命令來初始化一個 Debian 文件系統。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ debootstrap --arch=amd64 stable ~/DebianJessie</span></span></code></pre></div><p>以上默認你的架構是 x86_64。如果不是的話，你必須將架構的名稱改為 <code>amd64</code>。你可以使用 <code>uname -m</code> 得知你的機器架構。</p><p>一旦設置好你的根目錄，你就可以使用下面的命令來啓動你的容器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemd-nspawn -bD ~/DebianJessie</span></span></code></pre></div><p>容器將會在數秒後準備好並運行，當你試圖登錄時就會注意到：你無法使用你的系統上任何賬户。這是因為 <code>systemd-nspawn</code> 虛擬化了用户。修復的方法很簡單：將之前的命令中的 <code>-b</code> 移除即可。你將直接進入容器的 root 用户的 shell。此時，你只能使用 <code>passwd</code> 命令為 root 設置密碼，或者使用 <code>adduser</code> 命令添加一個新用户。一旦設置好密碼或添加好用户，你就可以把 <code>-b</code> 標誌添加回去然後繼續了。你會進入到熟悉的登錄控制台，然後你使用設置好的認證信息登錄進去。</p><p>以上對於任意你想在容器中運行的發行版都適用，但前提是你需要使用正確的包管理器創建系統。對於 Fedora，你應使用 DNF 而非 <code>debootstrap</code>。想要設置一個最小化的 Fedora 系統，你可以運行下面的命令，要將“/absolute/path/”替換成任何你希望容器存放的位置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf --releasever=24 --installroot=/absolute/path/ install systemd passwd dnf fedora-release</span></span></code></pre></div><p><img src="https://cdn.fedoramagazine.org/wp-content/uploads/2016/06/Screenshot-from-2016-06-17-15-04-14.png" alt=""></p><h3 id="設置網絡" tabindex="-1">設置網絡 <a class="header-anchor" href="#設置網絡" aria-label="Permalink to “設置網絡”">​</a></h3><p>如果你嘗試啓動一個服務，但它綁定了你宿主機正在使用的端口，你將會注意到這個問題：你的容器正在使用和宿主機相同的網絡接口。幸運的是，<code>systemd-nspawn</code> 提供了幾種可以將網絡從宿主機分開的方法。</p><h4 id="本地網絡" tabindex="-1">本地網絡 <a class="header-anchor" href="#本地網絡" aria-label="Permalink to “本地網絡”">​</a></h4><p>第一種方法是使用 <code>--private-network</code> 標誌，它默認僅創建一個迴環設備。這對於你不需要使用網絡的環境是非常理想的，例如構建系統和其它持續集成系統。</p><h4 id="多個網絡接口" tabindex="-1">多個網絡接口 <a class="header-anchor" href="#多個網絡接口" aria-label="Permalink to “多個網絡接口”">​</a></h4><p>如果你有多個網絡接口設備，你可以使用 <code>--network-interface</code> 標誌給容器分配一個接口。想要給我的容器分配 <code>eno1</code>，我會添加選項 <code>--network-interface=eno1</code>。當某個接口分配給一個容器後，宿主機就不能同時使用那個接口了。只有當容器徹底關閉後，宿主機才可以使用那個接口。</p><h4 id="共享網絡接口" tabindex="-1">共享網絡接口 <a class="header-anchor" href="#共享網絡接口" aria-label="Permalink to “共享網絡接口”">​</a></h4><p>對於我們中那些並沒有額外的網絡設備的人來説，還有其它方法可以訪問容器。一種就是使用 <code>--port</code> 選項。這會將容器中的一個端口定向到宿主機。使用格式是 <code>協議:宿主機端口:容器端口</code>，這裏的協議可以是 <code>tcp</code> 或者 <code>udp</code>，<code>宿主機端口</code> 是宿主機的一個合法端口，<code>容器端口</code> 則是容器中的一個合法端口。你可以省略協議，只指定 <code>宿主機端口:容器端口</code>。我通常的用法類似 <code>--port=2222:22</code>。</p><p>你可以使用 <code>--network-veth</code> 啓用完全的、僅宿主機模式的網絡，這會在宿主機和容器之間創建一個虛擬的網絡接口。你也可以使用 <code>--network-bridge</code> 橋接二者的連接。</p><h3 id="使用-systemd-組件" tabindex="-1">使用 systemd 組件 <a class="header-anchor" href="#使用-systemd-組件" aria-label="Permalink to “使用 systemd 組件”">​</a></h3><p>如果你容器中的系統含有 D-Bus，你可以使用 systemd 提供的實用工具來控制並監視你的容器。基礎安裝的 Debian 並不包含 <code>dbus</code>。如果你想在 Debian Jessie 中使用 <code>dbus</code>，你需要運行命令 <code>apt install dbus</code>。</p><h4 id="machinectl" tabindex="-1">machinectl <a class="header-anchor" href="#machinectl" aria-label="Permalink to “machinectl”">​</a></h4><p>為了能夠輕鬆地管理容器，systemd 提供了 <code>machinectl</code> 實用工具。使用 <code>machinectl</code>，你可以使用 <code>machinectl login name</code> 登錄到一個容器中、使用 <code>machinectl status name</code>檢查狀態、使用 <code>machinectl reboot name</code> 啓動容器或者使用 <code>machinectl poweroff name</code> 關閉容器。</p><h3 id="其它-systemd-命令" tabindex="-1">其它 systemd 命令 <a class="header-anchor" href="#其它-systemd-命令" aria-label="Permalink to “其它 systemd 命令”">​</a></h3><p>多數 systemd 命令，例如 <code>journalctl</code>, <code>systemd-analyze</code> 和 <code>systemctl</code>，都支持使用 <code>--machine</code> 選項來指定容器。例如，如果你想查看一個名為 “foobar” 的容器的日誌，你可以使用 <code>journalctl --machine=foobar</code>。你也可以使用 <code>systemctl --machine=foobar status service</code> 來查看運行在這個容器中的服務狀態。</p><p><img src="https://cdn.fedoramagazine.org/wp-content/uploads/2016/06/Screenshot-from-2016-06-17-15-09-25.png" alt=""></p><h3 id="和-selinux-一起工作" tabindex="-1">和 SELinux 一起工作 <a class="header-anchor" href="#和-selinux-一起工作" aria-label="Permalink to “和 SELinux 一起工作”">​</a></h3><p>如果你要使用 SELinux 強制模式（Fedora 默認模式），你需要為你的容器設置 SELinux 環境。想要那樣的話，你需要在宿主系統上運行下面兩行命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ semanage fcontext -a -t svirt_sandbox_file_t &quot;/path/to/container(/.*)?&quot;</span></span>
<span class="line"><span>$ restorecon -R /path/to/container/</span></span></code></pre></div><p>確保使用你的容器路徑替換 “/path/to/container”。對於我的容器 &quot;DebianJessie&quot;，我會運行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ semanage fcontext -a -t svirt_sandbox_file_t &quot;/home/johnmh/DebianJessie(/.*)?&quot;</span></span>
<span class="line"><span>$ restorecon -R /home/johnmh/DebianJessie/</span></span></code></pre></div><hr>`,37)),a("p",null,[e[6]||(e[6]=s("via: ",-1)),o(t,{href:"https://fedoramagazine.org/container-technologies-fedora-systemd-nspawn/"},{default:n(()=>[...e[5]||(e[5]=[s("https://fedoramagazine.org/container-technologies-fedora-systemd-nspawn/",-1)])]),_:1})]),a("p",null,[e[10]||(e[10]=s("作者：",-1)),o(t,{href:"https://fedoramagazine.org/container-technologies-fedora-systemd-nspawn/"},{default:n(()=>[...e[7]||(e[7]=[s("John M. Harris, Jr.",-1)])]),_:1}),e[11]||(e[11]=s(" 譯者：",-1)),o(t,{href:"https://github.com/chrisleegit"},{default:n(()=>[...e[8]||(e[8]=[s("ChrisLeeGit",-1)])]),_:1}),e[12]||(e[12]=s(" 校對：",-1)),o(t,{href:"https://github.com/wxy"},{default:n(()=>[...e[9]||(e[9]=[s("wxy",-1)])]),_:1})]),a("p",null,[e[15]||(e[15]=s("本文由 ",-1)),o(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[13]||(e[13]=[s("LCTT",-1)])]),_:1}),e[16]||(e[16]=s(" 原創編譯，",-1)),o(t,{href:"https://linux.cn/"},{default:n(()=>[...e[14]||(e[14]=[s("Linux中國",-1)])]),_:1}),e[17]||(e[17]=s(" 榮譽推出",-1))])])}const x=d(c,[["render",h]]);export{w as __pageData,x as default};
